function clamp(v,a,b){return Math.max(a,Math.min(b,v));}
function toHex(r,g,b){return '#'+[r,g,b].map(function(x){return ('0'+clamp(Math.round(x),0,255).toString(16)).slice(-2);}).join('').toUpperCase();}
function hexToRgb(h){
  h=h.trim().replace(/^#/,'');
  if(/^[0-9a-f]{3}$/i.test(h)){h=h[0]+h[0]+h[1]+h[1]+h[2]+h[2];}
  if(!/^[0-9a-f]{6}$/i.test(h)){return null;}
  return {r:parseInt(h.slice(0,2),16),g:parseInt(h.slice(2,4),16),b:parseInt(h.slice(4,6),16)};
}
function rgbToHsl(r,g,b){
  r/=255;g/=255;b/=255;
  var mx=Math.max(r,g,b),mn=Math.min(r,g,b),h=0,s=0,l=(mx+mn)/2,d=mx-mn;
  if(d){
    s=l>0.5?d/(2-mx-mn):d/(mx+mn);
    if(mx===r){h=((g-b)/d+(g<b?6:0));}
    else if(mx===g){h=(b-r)/d+2;}
    else {h=(r-g)/d+4;}
    h*=60;
  }
  return {h:Math.round(h),s:Math.round(s*100),l:Math.round(l*100)};
}
function hslToRgb(h,s,l){
  h=((h%360)+360)%360;s/=100;l/=100;
  var c=(1-Math.abs(2*l-1))*s,x=c*(1-Math.abs((h/60)%2-1)),m=l-c/2,r=0,g=0,b=0;
  if(h<60){r=c;g=x;} else if(h<120){r=x;g=c;} else if(h<180){g=c;b=x;}
  else if(h<240){g=x;b=c;} else if(h<300){r=x;b=c;} else {r=c;b=x;}
  return {r:(r+m)*255,g:(g+m)*255,b:(b+m)*255};
}
var E={hex:document.getElementById('hex'),rgb:document.getElementById('rgb'),hsl:document.getElementById('hsl'),
pick:document.getElementById('pick'),sw:document.getElementById('swatch'),note:document.getElementById('note')};
function paint(rgb,skip){
  var hex=toHex(rgb.r,rgb.g,rgb.b),hsl=rgbToHsl(rgb.r,rgb.g,rgb.b);
  if(skip!=='hex'){E.hex.value=hex;}
  if(skip!=='rgb'){E.rgb.value='rgb('+Math.round(rgb.r)+', '+Math.round(rgb.g)+', '+Math.round(rgb.b)+')';}
  if(skip!=='hsl'){E.hsl.value='hsl('+hsl.h+', '+hsl.s+'%, '+hsl.l+'%)';}
  E.pick.value=hex;E.sw.style.background=hex;
  var box=document.getElementById('shades');box.innerHTML='';
  [10,20,30,40,50,60,70,80,90].forEach(function(L){
    var c=hslToRgb(hsl.h,hsl.s,L),d=document.createElement('div');
    d.style.background=toHex(c.r,c.g,c.b);d.title=toHex(c.r,c.g,c.b);
    d.innerHTML='<span>'+L+'</span>';
    d.addEventListener('click',function(){paint(c);E.note.textContent='Switched to '+toHex(c.r,c.g,c.b)+'.';});
    box.appendChild(d);
  });
  E.note.textContent='HEX '+hex+' is the same color as rgb('+Math.round(rgb.r)+', '+Math.round(rgb.g)+', '+Math.round(rgb.b)+').';
  WT.resize();
}
E.hex.addEventListener('input',function(){var c=hexToRgb(E.hex.value);if(c){paint(c,'hex');}else{E.note.textContent='That is not a valid hex color. Use a form like #2952E3 or #29E.';}});
E.rgb.addEventListener('input',function(){
  var m=E.rgb.value.match(/(\d{1,3})\D+(\d{1,3})\D+(\d{1,3})/);
  if(m){paint({r:+m[1],g:+m[2],b:+m[3]},'rgb');}else{E.note.textContent='Enter three numbers, for example rgb(41, 82, 227).';}
});
E.hsl.addEventListener('input',function(){
  var m=E.hsl.value.match(/(-?\d{1,3})\D+(\d{1,3})\D+(\d{1,3})/);
  if(m){paint(hslToRgb(+m[1],+m[2],+m[3]),'hsl');}else{E.note.textContent='Enter three numbers, for example hsl(227, 69%, 53%).';}
});
E.pick.addEventListener('input',function(){var c=hexToRgb(E.pick.value);if(c){paint(c);}});
document.getElementById('cHex').addEventListener('click',function(){WT.copy(E.hex.value);E.note.textContent='HEX copied.';});
document.getElementById('cRgb').addEventListener('click',function(){WT.copy(E.rgb.value);E.note.textContent='RGB copied.';});
document.getElementById('cHsl').addEventListener('click',function(){WT.copy(E.hsl.value);E.note.textContent='HSL copied.';});
